import { v4 as uuidv4 } from 'uuid';

import { Plugin } from 'ckeditor5/src/core';
import { ClickObserver } from 'ckeditor5/src/engine';
import { Widget, toWidget } from 'ckeditor5/src/widget';

import '../../theme/file.css';

export default class FileEditing extends Plugin {
	static get requires() {
		return [ Widget ];
	}

	static get pluginName() {
		return 'FileEditing';
	}

	init() {
		const editor = this.editor;
		const schema = editor.model.schema;
		const conversion = editor.conversion;

		const fileUploadConfig = editor.config.get( 'fileUpload' );
		const downloadLinkRewriter = fileUploadConfig && fileUploadConfig.downloadLinkRewriter ?
			fileUploadConfig.downloadLinkRewriter : undefined;

		schema.register( 'file', {
			allowWhere: '$block',
			allowAttributes: [ 'id' ],
			isObject: true
		} );
		schema.register( 'fileInnerWrapper', {
			allowIn: 'file'
		} );
		schema.register( 'fileName', {
			allowIn: 'fileInnerWrapper',
			allowAttributes: [ 'name' ]
		} );
		schema.register( 'fileActionButtonsContainer', {
			allowIn: 'fileInnerWrapper'
		} );
		schema.register( 'downloadButton', {
			allowIn: 'fileActionButtonsContainer',
			allowAttributes: [ 'href' ]
		} );
		schema.register( 'deleteButton', {
			allowIn: 'fileActionButtonsContainer'
		} );

		// <file> and <fileInnerWrapper> convertors
		conversion.for( 'upcast' ).elementToElement( {
			model: ( viewElement, { writer } ) => {
				const id = viewElement.getAttribute( 'data-file-element-id' ) || uuidv4();
				return writer.createElement( 'file', { id } );
			},
			view: {
				name: 'div',
				classes: 'ck-file'
			}
		} );
		conversion.for( 'dataDowncast' ).elementToElement( {
			model: 'file',
			view: ( modelElement, { writer } ) => {
				const div = writer.createContainerElement( 'div', { class: 'ck-file' } );
				return div;
			}
		} ).attributeToAttribute( { view: 'data-file-element-id', model: 'id' } );
		conversion.for( 'editingDowncast' ).elementToElement( {
			model: 'file',
			view: ( modelElement, { writer } ) => {
				const div = writer.createContainerElement( 'div', { class: 'ck-file' } );
				return toWidget( div, writer );
			}
		} ).attributeToAttribute( { view: 'data-file-element-id', model: 'id' } );

		if ( downloadLinkRewriter instanceof Function ) {
			conversion.for( 'editingDowncast' ).add( dispatcher => {
				const converter = ( evt, data, conversionApi ) => {
					if ( !conversionApi.consumable.consume( data.item, evt.name ) ) {
						return;
					}

					const anchorEl = conversionApi.mapper.toViewElement( data.item );
					const hrefAttr = anchorEl.getAttribute( 'href' );
					const href = downloadLinkRewriter ?
						downloadLinkRewriter( hrefAttr, anchorEl ) :
						hrefAttr;

					anchorEl._attrs.set( 'href', href );
				};
				dispatcher.on( 'attribute:href', converter );
			} );
		}

		conversion.elementToElement( {
			model: 'fileInnerWrapper',
			view: {
				name: 'div',
				classes: 'ck-file-inner-wrapper'
			}
		} );

		// <fileName> convertors
		conversion.for( 'upcast' ).elementToElement( {
			model: ( viewElement, { writer } ) => {
				const name = viewElement.getChild( 0 ).data;
				return writer.createElement( 'fileName', { name } );
			},
			view: {
				name: 'span',
				classes: 'ck-file-name'
			}
		} );
		conversion.for( 'downcast' ).elementToStructure( {
			model: 'fileName',
			view: ( modelElement, { writer } ) => _createFileNameStructure( modelElement, writer )
		} );

		// <fileActionButtonsContainer>, <downloadButton>, <deleteButton> convertors
		conversion.elementToElement( {
			model: 'fileActionButtonsContainer',
			view: {
				name: 'div',
				classes: 'ck-file-buttons-container'
			}
		} );
		conversion.for( 'upcast' ).elementToElement( {
			model: 'downloadButton',
			view: {
				name: 'a',
				classes: 'ck-file-button-link'
			}
		} ).attributeToAttribute(
			{
				view: 'href',
				model: 'href'
			}
		);
		conversion.for( 'downcast' ).elementToElement( {
			model: 'downloadButton',
			view: ( modelElement, { writer } ) => _createDownloadLink( modelElement, writer )
		} ).attributeToAttribute( { model: 'href', view: 'href' } );
		conversion.for( 'upcast' ).elementToElement( {
			model: 'deleteButton',
			view: {
				name: 'button',
				classes: 'ck-file-button-delete'
			}
		} );
		conversion.for( 'downcast' ).elementToElement( {
			model: 'deleteButton',
			view: ( modelElement, { writer } ) => _createDeleteButton( modelElement, writer )
		} );

		// onclick event handler for delete button
		const view = editor.editing.view;
		const viewDocument = view.document;
		const model = editor.model;

		view.addObserver( ClickObserver );

		editor.listenTo( viewDocument, 'click', ( evt, data ) => {
			let target = data.target;
			if ( target.name === 'svg' ) {
				target = target.parent;
			}
			const modelElement = editor.editing.mapper.toModelElement( target );
			if ( modelElement && modelElement.name == 'deleteButton' ) {
				model.change( writer => {
					writer.remove( modelElement.findAncestor( 'file' ) );
				} );
			}
		} );
	}
}

function _createSVG( domDoc ) {
	const el = domDoc.createElementNS( 'http://www.w3.org/2000/svg', 'svg' );
	el.setAttribute( 'height', 16 );
	el.setAttribute( 'width', 16 );
	el.setAttribute( 'viewBox', '0 0 16 16' );
	el.setAttribute( 'class', 'icon' );
	return el;
}

function _createTooltip( viewWriter, tooltipText ) {
	return viewWriter.createUIElement( 'span', { class: 'tooltip-text' }, function( domDoc ) {
		const domElement = this.toDomElement( domDoc );
		domElement.innerHTML = tooltipText;
		return domElement;
	} );
}

function _createFillerText( viewWriter ) {
	// Adding an empty string to elements that are 'empty' prevents CKEditor5 from inserting `<br data-cke-filler="true" />`.
	// This is useful for elements such as the delete button and file download link which are deemed as empty since they do
	// not contain any text.
	// *See: https://ckeditor.com/docs/ckeditor5/latest/api/module_engine_view_filler.html
	return viewWriter.createText( '' );
}

function _createDownloadLink( modelElement, viewWriter ) {
	const downloadIcon = viewWriter.createUIElement( 'svg', null, function( domDoc ) {
		const svg = _createSVG( domDoc );
		// eslint-disable-next-line max-len
		svg.innerHTML = '<path d="M8 1a.5.5 0 0 1 .5.5v7.293l2.48-2.48a.5.5 0 1 1 .707.707l-3.333 3.334a.5.5 0 0 1-.708 0L4.313 7.02a.5.5 0 0 1 .707-.707l2.48 2.48V1.5A.5.5 0 0 1 8 1Z"/><path d="M2.5 10a.5.5 0 0 0-1 0v2.667A1.833 1.833 0 0 0 3.333 14.5h9.334a1.833 1.833 0 0 0 1.833-1.833V10a.5.5 0 0 0-1 0v2.667a.833.833 0 0 1-.833.833H3.333a.833.833 0 0 1-.833-.833V10Z"/>';
		return svg;
	} );
	const tooltip = _createTooltip( viewWriter, 'Download' );
	const href = modelElement.getAttribute( 'href' );
	const fillerText = _createFillerText( viewWriter );
	return viewWriter.createContainerElement( 'a', {
		href,
		target: '_blank',
		rel: 'noopener noreferrer',
		class: 'ck-file-button-link tooltip'
	}, [ fillerText, tooltip, downloadIcon ] );
}

function _createDeleteButton( modelElement, viewWriter ) {
	const deleteIcon = viewWriter.createUIElement( 'svg', null, function( domDoc ) {
		const svg = _createSVG( domDoc );
		// eslint-disable-next-line max-len
		svg.innerHTML = '<path d="M2.04 3.5H1a.5.5 0 0 1 0-1h4V2A1.5 1.5 0 0 1 6.5.5h3A1.5 1.5 0 0 1 11 2v.5h4a.5.5 0 1 1 0 1h-1.04l-.885 10.624A1.5 1.5 0 0 1 11.58 15.5H4.42a1.5 1.5 0 0 1-1.494-1.376L2.04 3.5Zm1.003 0 .88 10.541a.5.5 0 0 0 .498.459h7.159a.5.5 0 0 0 .498-.459L12.957 3.5H3.043ZM6 2.5h4V2a.5.5 0 0 0-.5-.5h-3A.5.5 0 0 0 6 2v.5Zm1 9a.5.5 0 1 1-1 0v-5a.5.5 0 0 1 1 0v5Zm3 0a.5.5 0 1 1-1 0v-5a.5.5 0 0 1 1 0v5Z"/>';
		return svg;
	} );
	const tooltip = _createTooltip( viewWriter, 'Remove' );
	const fillerText = _createFillerText( viewWriter );
	return viewWriter.createContainerElement( 'button', {
		class: 'ck-file-button-delete tooltip'
	}, [ fillerText, tooltip, deleteIcon ] );
}

function _createPaperclipIcon( viewWriter ) {
	return viewWriter.createUIElement( 'svg', null, function( domDoc ) {
		const svg = _createSVG( domDoc );
		// eslint-disable-next-line max-len
		svg.innerHTML = '<path d="m14.293 7.367-6.126 6.126a4.002 4.002 0 1 1-5.66-5.66l6.126-6.126a2.668 2.668 0 1 1 3.774 3.773l-6.134 6.127A1.334 1.334 0 0 1 4.387 9.72l5.66-5.653" stroke-linecap="round" stroke-linejoin="round"/>';
		return svg;
	} );
}

function _createFileNameStructure( modelElement, viewWriter ) {
	const icon = _createPaperclipIcon( viewWriter );
	const fileName = viewWriter.createText( modelElement.getAttribute( 'name' ) );
	const span = viewWriter.createContainerElement( 'span', { class: 'ck-file-name' }, [ fileName ] );
	return viewWriter.createContainerElement( 'div', { class: 'ck-file-name-container' }, [ icon, span ] );
}
